const home=main.innerHTML;
const areaSwitches=$$('button').filter(b=>!nav.contains(b)&&/后台|返回前台/.test(b.textContent));
const menus={"detail":[["basic","基础资料","基金资料"],["manager","基金经理"],["nav","净值走势"],["share","份额规模"],["dividend","分红记录"],["comparison","同类对比"],["rating","基金评级"],["holdings","基金持仓","投资与动态"],["company","持仓公司经营"],["documents","公告与动态"]],"watched":[["basic","基础资料","关注资料"],["manager","基金经理"],["nav","净值走势"],["share","份额规模"],["dividend","分红记录"],["comparison","同类对比"],["rating","基金评级"],["holdings","基金持仓","投资与动态"],["company","持仓公司经营"],["documents","公告与动态"],["research","走势预测","预测与回看"],["prediction-history","预测历史"],["rules","我的提醒","我的设置"]],"portfolio":[["overview","总览"],["holdings","持仓"],["orders","交易记录"],["earnings","收益明细"],["plans","定投计划"],["funding","本人资金安排"],["account-risk","已录入持仓检查"],["options","调整前的条件比较"]],"advice":[["latest","最新建议","持仓分析"],["diagnosis","诊断详情"],["rules","规则草案"],["history","历史记录"],["review","效果回看"]],"notifications":[["messages","已触发提醒"],["rules","提醒规则"]],"managers":[["directory","经理查找"]],"managerDetail":[["funds","在管基金"],["history","历史任职"],["profile","职业履历"],["performance","任期表现"],["disclosures","相关披露"]],"dashboard":[["overview","工作概览"]],"users":[["accounts","账户列表"],["credits","关注积分"],["ledger","积分流水"],["sim-portfolio","持仓详情"],["migration","历史关注迁移"]],"sync":[["overview","任务总览"],["marketNav","净值增量同步","任务分类"],["freeDataCompletion","基金资料与市场数据更新"],["fundManagers","基金经理资料更新"],["fundMaterials","基金持仓与公司资料更新"],["fundRatings","基金评级更新"],["fundNews","近期基金公告核验"],["featureSnapshot","历史指标计算"],["direction1dPrediction","一日综合预测"],["simulationFees","模拟费率同步"],["spxManual","标普500手动同步"],["simRecurring","定投手动执行"],["notes","运行说明","帮助"]],"fees":[],"profile":[["overview","基本信息"],["name","修改姓名"]],"system":[["palette","整体配色"],["controls","表单与筛选"],["dialogs","弹窗与提示"],["states","涨跌与状态"]]};
const labels={market:'基金市场',managers:'基金经理',watchlist:'我的关注',portfolio:'我的持仓',advice:'持仓分析',notifications:'站内提醒',profile:'个人信息',dashboard:'工作台',sync:'数据同步',users:'用户管理',fees:'费率维护'};
const userModules=['market','managers','watchlist','portfolio','advice','notifications'],adminModules=['dashboard','sync','users','fees'];
const funds=[{id:'001021',name:'华夏亚债中国债券指数-A',type:'债券型',nav:1.32,change:-.09,value:18240,profit:415.2,rate:2.33},{id:'005827',name:'易方达蓝筹精选混合',type:'混合型',nav:1.8246,change:1.28,value:52308.67,profit:7864.2,rate:17.7},{id:'161725',name:'招商中证白酒指数',type:'指数型',nav:1.1472,change:-.64,value:28460,profit:-3215.6,rate:-10.15},{id:'003095',name:'中欧医疗健康混合',type:'混合型',nav:1.7689,change:0,value:21840.32,profit:-1276.54,rate:-5.52},{id:'161005',name:'富国天惠成长混合',type:'混合型',nav:1.5621,change:.75,value:15731.28,profit:2355.1,rate:17.61},{id:'000198',name:'天弘余额宝货币',type:'货币型',nav:1,change:null,value:15000,profit:35.6,rate:.24},{id:'006132',name:'广发中证全指信息技术ETF联接',type:'指数型',nav:1.7634,change:1.42,value:19520.18,profit:1083.2,rate:5.87}];
const users=Array.from({length:12},(_,i)=>({id:'user'+i,name:['林同学','陈女士','周先生','许同学','王女士','李先生'][i%6],mobile:'138****'+(6821+i*37),role:i===2?'管理员':'普通用户',status:i%5===4?'已停用':'正常',credits:1000+i*100,quota:50+i*10,date:'2026-11-'+String(12-i%10).padStart(2,'0')}));
const types=['货币型','债券型','混合型','股票型','指数型','QDII','基金中基金（FOF）','其他类型'];
const demoOrders=[{id:'demo-1',fund:'001021',date:'2026-11-12',amount:2000,status:'示例已确认'},{id:'demo-2',fund:'005827',date:'2026-11-10',amount:500,status:'示例已确认'}];
const demoPlans=[{id:'plan-1',fund:'005827',amount:500,cycle:'每周',date:'2026-11-13',status:'示例计划'}];
const state={area:'user',module:scheme==='research'?'market':'portfolio',section:scheme==='workbook'?'holdings':'overview',view:'list',selected:'001021',quick:scheme==='research',quickTab:'overview',detailSection:'basic',managerDetail:false,returnTo:null,lists:{},followed:new Set(['001021','005827','161725','003095']),period:'近1月'};
let listing=false,lastFocus=null,modalHandler=null,toastTimer;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const tone=n=>n==null||n===0?'ix-flat':n>0?'ix-up':'ix-down';const sign=n=>n==null?'—':(n>0?'+':n<0?'−':'')+num(Math.abs(n));const pct=n=>`<span class="${tone(n)}">${sign(n)}${n==null?'':'%'}</span>`;
const fund=()=>funds.find(f=>f.id===state.selected)||funds[0];const user=()=>users.find(u=>u.id===state.selected)||users[0];
const prefs=()=>state.lists[state.module]||(state.lists[state.module]={keyword:'',type:'',page:1,size:5,sort:false,status:'',role:''});
const action=(name,text,primary=false)=>`<button class="ix-button ${primary?'ix-primary':''}" data-ix-action="${name}">${text}</button>`;
const note=(text,kind='')=>`<div class="ix-note ${kind}">${text}</div>`;
const empty=(text,sub='')=>`<div class="ix-empty">${text}<small>${sub}</small></div>`;
const kv=(k,v)=>`<div class="ix-kv"><span>${k}</span><span>${v}</span></div>`;
const header=(title,desc,buttons='')=>`<div class="ix-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="ix-inline">${buttons}</div></div>`;
const tabs=(items,current,attr='section')=>`<nav class="ix-tabs" aria-label="页面栏目">${items.map(([k,l])=>`<button data-ix-${attr}="${k}" class="${k===current?'active':''}" ${k===current?'aria-current="page"':''}>${l}</button>`).join('')}</nav>`;
function toast(text){$('#ix-toast').textContent=text;$('#ix-toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#ix-toast').hidden=true,3000)}
function globalNav(){nav.innerHTML=(state.area==='admin'?adminModules:userModules).map(m=>`<button data-ix-module="${m}" ${state.module===m?'class="active" aria-current="page"':''}>${labels[m]}</button>`).join('');areaSwitches.forEach(b=>{b.dataset.ixAction='switch-area';b.textContent=state.area==='admin'?'返回前台':'管理后台'});const breadcrumb=$('.topbar>span');if(breadcrumb)breadcrumb.textContent=(state.area==='admin'?'后台管理':'我的投资')+' / '+labels[state.module];$$('.status,.badge').forEach(b=>b.textContent='可点击 · 示例数据')}
function route(module,section){closeQuick(false);state.module=module;state.area=adminModules.includes(module)?'admin':'user';state.view='list';state.managerDetail=false;state.section=section||(module==='portfolio'?'overview':module==='users'?'accounts':menus[module]?.[0]?.[0]||'');render()}
function switchArea(){route(state.area==='user'?'users':'portfolio')}
function accountTabs(){const primary=['overview','holdings','earnings','orders','plans'];const secondary=['funding','account-risk','options'];return `<nav class="ix-tabs" aria-label="账户栏目">${primary.map(k=>{const label=menus.portfolio.find(x=>x[0]===k)[1];return `<button data-ix-section="${k}" class="${k===state.section?'active':''}" ${k===state.section?'aria-current="page"':''}>${label}</button>`}).join('')}<details class="ix-account-pop"><summary>账户管理</summary><div>${secondary.map(k=>`<button data-ix-section="${k}">${menus.portfolio.find(x=>x[0]===k)[1]}</button>`).join('')}</div></details></nav>`}
function panel(title,body){return `<section class="ix-panel"><h2>${title}</h2>${body}</section>`}
function render(){listing=false;globalNav();if(state.view==='full'){renderFull();renderQuick();return}if(state.module==='portfolio'&&['overview','holdings'].includes(state.section)){if(scheme!=='research'){main.innerHTML=home;const overview=$('.overview',main);if(overview)overview.hidden=state.section==='holdings';markHome();listing=true;bindList();setActiveTabs()}else main.innerHTML=header('我的持仓','模拟账户 · 示例数据',action('plan','设置定投')+action('buy','模拟买入 / 加仓',true))+accountTabs()+summary()+listShell('持有的基金');if(scheme==='research'){listing=true;bindList()}}
else if(['market','watchlist'].includes(state.module)){if(scheme==='research'&&state.module==='market'){main.innerHTML=home;markHome();listing=true;bindList()}else{main.innerHTML=header(labels[state.module],'净值截至 2026-11-11 · 示例数据')+listShell(state.module==='watchlist'?'关注的基金':'基金列表');listing=true;bindList()}}
else if(state.module==='users'&&state.section==='accounts'){main.innerHTML=header('用户管理','在列表中查看账户，打开右侧详情后管理积分和持仓。')+tabs(menus.users,state.section)+listShell('账户列表',true);listing=true;bindList()}
else renderOther();renderQuick();bindGenericInputs()}
function summary(){return `<div class="ix-stat-row"><div><label>持仓总市值（元）</label><strong>171,100.45</strong></div><div><label>当日收益（元）</label><strong class="ix-up">+1,236.80</strong></div><div><label>持有收益（元）</label><strong class="ix-up">+7,261.16</strong></div></div>`}
function listShell(title,admin=false){return `<section class="ix-panel"><h2>${title}</h2><div class="ix-toolbar"><input class="ix-input" data-ix-filter="keyword" aria-label="${admin?'搜索姓名或手机号':'搜索基金名称或代码'}" placeholder="${admin?'搜索姓名 / 手机号':'搜索基金名称 / 代码'}"><select class="ix-select" data-ix-filter="${admin?'status':'type'}" aria-label="${admin?'账户状态':'基金类型'}"><option value="">${admin?'全部状态':'全部类型'}</option>${(admin?['正常','已停用']:types).map(t=>`<option>${t}</option>`).join('')}</select>${admin?'<select class="ix-select" data-ix-filter="role" aria-label="角色"><option value="">全部角色</option><option>普通用户</option><option>管理员</option></select>':''}${action('query','查询')}${action('reset','重置')}</div><div class="ix-table-wrap"><table class="ix-table"><thead></thead><tbody></tbody></table></div><div class="ix-pages" data-ix-pages></div></section>`}
function markHome(){const search=$('input',main);if(search)search.dataset.ixFilter='keyword';const select=scheme==='research'?null:$('select',main);if(select){select.dataset.ixFilter='type';select.innerHTML='<option value="">全部类型</option>'+types.map(t=>`<option>${t}</option>`).join('')}const sort=scheme==='research'?$('.filters select',main):null;if(sort){sort.dataset.ixFilter='sort';sort.innerHTML='<option value="false">按基金代码排序</option><option value="true">按日涨跌幅排序</option>'}if(scheme==='research')$$('.filters button',main).forEach(b=>b.dataset.ixType=b.textContent.trim()==='全部类型'?'':b.textContent.trim());$$('.periods button',main).forEach(b=>b.dataset.ixPeriod=b.textContent.trim());const account=$('.account-menu',main);if(account){account.outerHTML=`<details class="ix-account-pop"><summary>账户管理</summary><div>${menus.portfolio.slice(5).map(([k,l])=>`<button data-ix-section="${k}">${l}</button>`).join('')}</div></details>`}$$('.tabs button',main).forEach(b=>{const entry=menus.portfolio.find(x=>x[1]===b.textContent.trim());if(entry)b.dataset.ixSection=entry[0]});const pageBox=$(scheme==='overview'?'.pages':'.pagination',main);if(pageBox)pageBox.dataset.ixPages='';const title=scheme==='overview'?$('.holding-head h2 small',main):$('.section-heading h2 small',main);if(title)title.textContent='7 只 · 示例';const h1=$('h1',main);if(h1&&!$('.ix-live-badge',main))h1.insertAdjacentHTML('beforeend','<small class="ix-live-badge">可点击预览</small>')}
function setActiveTabs(){$$('[data-ix-section]',main).forEach(b=>{b.classList.toggle('active',b.dataset.ixSection===state.section);if(b.dataset.ixSection===state.section)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}
function bindGenericInputs(){$$('[data-ix-filter]',main).forEach(el=>{const key=el.dataset.ixFilter;el.value=String(prefs()[key]??'')})}
function bindList(){bindGenericInputs();renderRows()}
function listItems(){const p=prefs();if(state.module==='users')return users.filter(u=>(u.name+u.mobile).includes(p.keyword)&&(!p.status||u.status===p.status)&&(!p.role||u.role===p.role));let result=funds.filter(f=>(f.name+f.id).includes(p.keyword)&&(!p.type||f.type===p.type)&&(state.module!=='watchlist'||state.followed.has(f.id)));if(p.sort)result=[...result].sort((a,b)=>(b.change??-Infinity)-(a.change??-Infinity));return result}
function renderRows(){if(!listing)return;const p=prefs(),items=listItems(),admin=state.module==='users',portfolio=state.module==='portfolio';const count=Math.max(1,Math.ceil(items.length/p.size));p.page=Math.max(1,Math.min(p.page,count));const table=$('table',main);$('thead',table).innerHTML=admin?'<tr><th>账户 / 手机号</th><th>角色</th><th>状态</th><th class="right num">积分</th><th class="right num">操作</th></tr>':`<tr><th>基金名称 / 代码</th><th class="right num">${portfolio?'持有金额（元）':'单位净值'}</th><th class="right num">${portfolio?'持有收益（元）':'日涨跌幅'}</th><th class="right num">${portfolio?'收益率':'类型'}</th><th class="right num">操作</th></tr>`;
$('tbody',table).innerHTML=items.slice((p.page-1)*p.size,p.page*p.size).map(x=>admin?`<tr data-ix-record="${x.id}" class="${state.quick&&state.selected===x.id?'ix-selected':''}"><td><button class="ix-name-button" data-ix-open="${x.id}">${x.name}<small>${x.mobile}</small></button></td><td>${x.role}</td><td>${x.status}</td><td class="right num">${x.credits}</td><td class="right num"><button class="ix-link" data-ix-open="${x.id}">查看详情</button></td></tr>`:`<tr data-ix-record="${x.id}" class="${state.quick&&state.selected===x.id?'ix-selected':''}"><td class="name"><button class="ix-name-button" data-ix-open="${x.id}">${x.name}<small>${x.id} · ${x.type}</small></button></td><td class="right num">${portfolio?num(x.value):x.nav.toFixed(4)}</td><td class="right num ${tone(portfolio?x.profit:x.change)}">${portfolio?sign(x.profit):pct(x.change)}</td><td class="right num">${portfolio?pct(x.rate):x.type}</td><td class="right num"><button class="ix-link" data-ix-open="${x.id}">${scheme==='research'?'查看':'快速查看'}</button></td></tr>`).join('')||`<tr><td colspan="5">${empty('没有符合条件的记录','请调整关键词或筛选条件。')}<button class="ix-link" data-ix-action="reset">清除筛选</button></td></tr>`;
const pages=$('[data-ix-pages]',main);if(pages){pages.classList.add('ix-pages');pages.innerHTML=`<span role="status">共 ${items.length} ${admin?'个账户':'只基金'}，第 ${p.page} / ${count} 页</span><div><button class="ix-page" data-ix-page="${p.page-1}" ${p.page===1?'disabled':''}>上一页</button>${Array.from({length:count},(_,i)=>`<button class="ix-page ${p.page===i+1?'active':''}" data-ix-page="${i+1}" ${p.page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button class="ix-page" data-ix-page="${p.page+1}" ${p.page===count?'disabled':''}>下一页</button><select class="ix-select" data-ix-filter="size" aria-label="每页条数"><option value="5">5 条 / 页</option><option value="10">10 条 / 页</option></select></div>`;$('select',pages).value=String(p.size)}
$$('[data-ix-type]',main).forEach(b=>b.classList.toggle('active',b.dataset.ixType===p.type))}
function openQuick(id){lastFocus=document.activeElement;state.selected=id;state.quick=true;state.quickTab='overview';renderQuick();if(listing)$$('[data-ix-record]',main).forEach(el=>el.classList.toggle('ix-selected',el.dataset.ixRecord===id))}
function closeQuick(refresh=true){state.quick=false;$('#ix-drawer').hidden=true;if(refresh){renderQuick();if(lastFocus?.isConnected)lastFocus.focus();$$('[data-ix-record]',main).forEach(el=>el.classList.remove('ix-selected'))}}
function chartSvg(nav=false){const f=fund();const period=state.period;const values=nav?Array.from({length:21},(_,i)=>f.nav-.012+(.012*i/20)+Math.sin(i*1.7)*.004):Array.from({length:25},(_,i)=>150+(7261.16-150)*i/24+Math.sin(i*1.5)*250);values[values.length-1]=nav?f.nav:7261.16;const low=nav?f.nav-.025:0,high=nav?f.nav+.015:8000;const points=values.map((v,i)=>[42+i*650/(values.length-1),168-(v-low)*140/(high-low)]);const line=points.map(([x,y],i)=>(i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)).join(' ');const days=period==='近1月'?30:period==='近3月'?90:180;const tickDate=i=>{const d=new Date('2026-11-13T12:00:00+08:00');d.setUTCDate(d.getUTCDate()-Math.round(days*(1-i/3)));return String(d.getUTCMonth()+1).padStart(2,'0')+'-'+String(d.getUTCDate()).padStart(2,'0')};return `<svg class="ix-chart chart" viewBox="0 0 720 205" role="img" aria-label="${nav?'单位净值':'持有收益'}${period}变化，全部为示例"><g stroke="#e5ebe1" fill="none">${[28,74,121,168].map(y=>`<path d="M42 ${y}H692"/>`).join('')}</g><g class="ix-chart-label">${[high,high-(high-low)/3,high-2*(high-low)/3,low].map((v,i)=>`<text x="1" y="${32+i*46}">${nav?v.toFixed(4):Math.round(v).toLocaleString()}</text>`).join('')}${[0,1,2,3].map(i=>`<text x="${42+i*211}" y="194">${tickDate(i)}</text>`).join('')}</g><path d="${line} L692 168 L42 168Z" fill="#e7f0e4"/><path d="${line}" fill="none" stroke="#4d805c" stroke-width="2.3"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="2" fill="#4d805c"><title>${i+1}：${values[i].toFixed(nav?4:2)} ${nav?'元':'元收益'}（示例）</title></circle>`).join('')}</svg>`}
function quickFundHtml(){const f=fund();const t=state.quickTab;return `<div class="ix-drawer-head"><span>基金速览 · 示例数据</span><button class="ix-close" data-ix-action="close-quick" aria-label="关闭基金速览">关闭</button></div><h2>${f.name}</h2><div class="ix-caption">${f.id} · ${f.type}</div><div class="ix-stat-row"><div><label>单位净值</label><strong>${f.nav.toFixed(4)}</strong></div><div><label>日涨跌幅</label><strong class="${tone(f.change)}">${sign(f.change)}${f.change==null?'':'%'}</strong></div></div>${tabs([['overview','概况'],['nav','表现'],['holdings','我的持有'],['documents','公告']],t,'quick-tab')}${t==='nav'?chartSvg(true):t==='holdings'?kv('持有金额',num(f.value)+' 元')+kv('持有收益',`<span class="${tone(f.profit)}">${sign(f.profit)} 元</span>`)+kv('收益率',pct(f.rate)):t==='documents'?empty('暂无公告示例','完整公告入口继续保留。'):kv('基金类型',f.type)+kv('净值日期','2026-11-11')+kv('示例状态','正常运作')}<div class="ix-actions">${action('full','打开完整资料',true)}<div class="ix-inline">${action('buy','模拟买入')}${action('plan','设置定投')}</div><button class="ix-link" data-ix-action="follow">${state.followed.has(f.id)?'取消关注':'加入关注'}</button></div>${note('数据和操作均为设计演示，不连接真实账户。')}`}
function quickUserHtml(){const u=user(),t=state.quickTab;const tabsData=[['overview','账户详情'],['credits','关注积分'],['ledger','积分流水'],['sim-portfolio','持仓详情'],['migration','历史关注迁移']];return `<div class="ix-drawer-head"><span>账户速览 · 示例</span><button class="ix-close" data-ix-action="close-quick" aria-label="关闭账户速览">关闭</button></div><h2>${u.name}</h2><div class="ix-caption">${u.mobile}</div>${tabs(tabsData,t,'quick-tab')}${t==='overview'?kv('角色',u.role)+kv('状态',u.status)+kv('创建日期',u.date):t==='credits'?kv('试用积分',u.credits)+kv('关注额度',u.quota)+action('grant','发放积分',true):t==='ledger'?kv('2026-11-11','示例发放 +1,000'):t==='sim-portfolio'?kv('账户类型','模拟账户')+kv('持有基金','2 只 · 示例')+kv('持有市值','36,240.00 元'):empty('暂无迁移示例','历史迁移入口保留。')}<div class="ix-actions">${action('reset-password','重置密码')}</div>${note('只管理预览数据，不修改真实用户。')}`}
function renderQuick(){const embedded=scheme==='research'?$('.detail'):null;const canEmbed=!!embedded&&state.area==='user'&&['market','watchlist','portfolio'].includes(state.module)&&state.view!=='full'&&matchMedia('(min-width:881px)').matches;if(embedded)document.body.classList.toggle('ix-no-pane',!canEmbed||!state.quick);if(!state.quick){$('#ix-drawer').hidden=true;return}const html=state.module==='users'?quickUserHtml():quickFundHtml();if(canEmbed){embedded.innerHTML=html;embedded.style.display='';$('#ix-drawer').hidden=true}else{$('#ix-drawer').innerHTML=html;$('#ix-drawer').hidden=false}}
function enterFull(){state.returnTo={module:state.module,section:state.section,selected:state.selected,quick:state.quick};state.view='full';state.detailSection='basic';state.quick=false;render()}
function returnList(){const saved=state.returnTo;if(saved)Object.assign(state,saved);state.view='list';state.returnTo=null;render()}
function renderFull(){const f=fund(),items=state.module==='watchlist'?menus.watched:menus.detail;const selected=items.find(x=>x[0]===state.detailSection)||items[0];state.detailSection=selected[0];let content='';if(selected[0]==='basic')content=`<div class="ix-stat-row"><div><label>单位净值</label><strong>${f.nav.toFixed(4)}</strong></div><div><label>日涨跌幅</label><strong class="${tone(f.change)}">${sign(f.change)}${f.change==null?'':'%'}</strong></div></div><div class="ix-data-grid">${[['基金代码',f.id],['基金类型',f.type],['基金管理人',f.id==='001021'?'华夏基金管理有限公司':'示例基金管理人'],['净值日期','2026-11-11'],['运作方式','开放式'],['资料用途','界面交互示例']].map(([k,v])=>`<div class="ix-data-item"><label>${k}</label><span>${v}</span></div>`).join('')}</div>`;else if(selected[0]==='nav')content=`<div class="ix-inline">${['近1月','近3月','近半年','全部'].map(p=>`<button class="ix-button ${p===state.period?'ix-primary':''}" data-ix-period="${p}">${p}</button>`).join('')}</div>${chartSvg(true)}`;else if(selected[0]==='manager')content='<div class="ix-kv"><span>陈经理 · 示例资料</span><button class="ix-link" data-ix-action="manager-detail">查看经理</button></div>';else if(selected[0]==='rules')content=action('reminder','设置提醒',true)+empty('暂无提醒示例');else content=empty('暂无'+selected[1]+'示例','已保留入口；此预览不编造实际分析、公告或分红结果。');main.innerHTML=`<button class="ix-back" data-ix-action="return-list">返回${labels[state.returnTo?.module]||'基金列表'} · 保留筛选与页码</button>${header(f.name,f.id+' · '+f.type+' · 示例数据',action('buy','模拟买入',true)+action('plan','设置定投'))}${tabs(items,state.detailSection,'detail-section')}${panel(selected[1],content)}`}
function renderOther(){const module=state.module;let items=module==='managers'?(state.managerDetail?menus.managerDetail:menus.managers):menus[module]||[];if(items.length&&!items.some(x=>x[0]===state.section))state.section=items[0][0];const label=items.find(x=>x[0]===state.section)?.[1]||labels[module];let body='';const portfolio=module==='portfolio';const local=portfolio?accountTabs():tabs(items,state.section);
if(portfolio&&state.section==='earnings')body=`<table class="ix-table"><thead><tr><th>收益日期</th><th class="ix-num">收益（元）</th><th>状态</th></tr></thead><tbody><tr><td>2026-11-13</td><td class="ix-num ix-up">+1,236.80</td><td>示例已更新</td></tr><tr><td>2026-11-12</td><td class="ix-num ix-down">−286.30</td><td>示例已更新</td></tr><tr><td>2026-11-11</td><td class="ix-num ix-flat">—</td><td>等待数据</td></tr></tbody></table>`;
else if(portfolio&&state.section==='orders')body=`<table class="ix-table"><thead><tr><th>基金</th><th>申请日期</th><th class="ix-num">金额（元）</th><th>状态</th></tr></thead><tbody>${demoOrders.map(o=>`<tr><td>${funds.find(f=>f.id===o.fund)?.name}</td><td>${o.date}</td><td class="ix-num">${num(o.amount)}</td><td>${o.status}</td></tr>`).join('')}</tbody></table>`;
else if(portfolio&&state.section==='plans')body=action('plan','设置定投',true)+`<table class="ix-table ix-group-space"><thead><tr><th>基金</th><th>周期</th><th class="ix-num">每期金额（元）</th><th>操作</th></tr></thead><tbody>${demoPlans.map(p=>`<tr><td>${funds.find(f=>f.id===p.fund)?.name}<small>${p.status}</small></td><td>${p.cycle}</td><td class="ix-num">${num(p.amount)}</td><td><button class="ix-link" data-ix-edit-plan="${p.id}">修改</button></td></tr>`).join('')}</tbody></table>`;
else if(module==='managers'){body=state.managerDetail?empty('暂无'+label+'的真实示例','经理详情全部栏目保留。'):`<div class="ix-toolbar"><input class="ix-input" id="ix-manager-query" aria-label="搜索基金经理" placeholder="搜索基金经理"><button class="ix-button" data-ix-action="find-manager">查询</button></div><div id="ix-manager-results">${['陈经理','林经理','周经理'].map(n=>`<div class="ix-kv"><span>${n} · 示例</span><button class="ix-link" data-ix-manager="${n}">查看详情</button></div>`).join('')}</div>`}
else if(module==='notifications')body=(state.section==='rules'?action('reminder','设置提醒',true):'')+empty('暂无提醒示例','可切换“提醒规则”并体验设置表单。');
else if(module==='profile')body=kv('姓名','林同学')+kv('手机号','138****6821')+`<div class="ix-inline ix-group-space">${action('edit-name','修改姓名')}<button class="ix-link" data-ix-action="signout">退出登录</button></div>`;
else if(module==='users'&&state.section==='credits')body=action('pick-user','选择示例账户',true)+note('选择账户后，在详情抽屉中查看和发放关注积分。');
else if(module==='sync')body=state.section==='notes'?note('本预览不启动任何实际同步、预测、定投或其他后台任务。','warning'):`<label class="ix-form-label">选择任务<select class="ix-select" id="ix-sync-task">${menus.sync.filter(x=>!['overview','notes'].includes(x[0])).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></label>${action('sync-preview','查看执行确认',true)}`;
else if(module==='fees')body=action('fee-form','维护费率示例',true)+empty('暂无费率规则示例','操作只影响本次演示。');
else body=empty('暂无'+label+'示例','栏目可切换，当前只展示交互流程与状态，不读取真实业务数据。');
main.innerHTML=header(labels[module],label+' · 示例数据')+local+panel(label,body)}
function showModal(title,body,submit,callback,danger=false){const dialog=$('#ix-modal');lastFocus=document.activeElement;$('#ix-modal-title').textContent=title;$('#ix-modal-content').innerHTML=body;$('#ix-modal-submit').hidden=!submit;$('#ix-modal-submit').textContent=submit||'';$('#ix-modal-submit').className='ix-button '+(danger?'ix-danger':'ix-primary');$('#ix-modal-cancel').textContent=submit?'取消':'关闭';modalHandler=callback||null;if(!dialog.open)dialog.showModal()}
function closeModal(){const d=$('#ix-modal');if(d.open)d.close();modalHandler=null;if(lastFocus?.isConnected)lastFocus.focus()}
function form(title,fields,save){showModal(title,`<form id="ix-form">${fields.map(([key,label,type,placeholder,value])=>`<label class="ix-form-label">${label}${type==='select'?`<select class="ix-select" name="${key}" required>${placeholder.map(v=>{const option=typeof v==='string'?{value:v,label:v}:v;return `<option value="${esc(option.value)}" ${option.value===value?'selected':''}>${esc(option.label)}</option>`}).join('')}</select>`:`<input class="ix-input" name="${key}" type="${type}" ${type==='number'?'min="0.01" step="0.01"':''} ${type==='date'?`value="${value||'2026-11-13'}"`:`placeholder="${esc(placeholder)}" value="${esc(value||'')}"`} required maxlength="80">`}</label>`).join('')}<div class="ix-form-error" role="alert" id="ix-form-error" hidden></div>${note('只生成本次预览的示例记录，不提交真实业务。')}</form>`,'确认预览',()=>{const f=$('#ix-form');if(!f.reportValidity())return false;const data=Object.fromEntries(new FormData(f));save?.(data);toast('示例操作已完成，未提交真实业务。')})}
function fundOptions(){return funds.map(f=>({value:f.id,label:f.name}))}
function buy(){form('模拟买入 / 加仓',[['fund','基金','select',fundOptions(),fund().id],['amount','买入金额（元）','number','请输入金额'],['date','申请日期','date','']],data=>{demoOrders.unshift({id:'preview-'+Date.now(),fund:data.fund,amount:Number(data.amount),date:data.date,status:'预览草稿 · 未提交'});if(state.module==='portfolio'&&state.section==='orders')render()})}
function plan(editId){const p=demoPlans.find(p=>p.id===editId);form(p?'修改定投计划':'设置定投',[['fund','基金','select',fundOptions(),p?.fund||fund().id],['amount','每期金额（元）','number','请输入金额',p?.amount],['cycle','定投周期','select',['每周','每月'],p?.cycle||'每周'],['date','开始日期','date','',p?.date]],data=>{const item={id:p?.id||'preview-plan-'+Date.now(),fund:data.fund,amount:Number(data.amount),cycle:data.cycle,date:data.date,status:'预览计划 · 不执行'};if(p)Object.assign(p,item);else demoPlans.unshift(item);if(state.module==='portfolio'&&state.section==='plans')render()})}
function reminder(){form('设置提醒',[['condition','提醒条件','select',['净值变化','持有收益变化']],['description','提醒说明','text','请输入说明']],()=>{})}
function refreshChart(period){state.period=period;if(state.view==='full')renderFull();else{const existing=$('.chart',main);if(existing)existing.outerHTML=chartSvg(false);$$('[data-ix-period]',main).forEach(b=>b.classList.toggle('active',b.dataset.ixPeriod===period))}}
const actions={buy,plan,reminder,profile:()=>route('profile'),full:enterFull,'return-list':returnList,'close-quick':()=>closeQuick(),'close-modal':closeModal,query:()=>{prefs().page=1;renderRows()},reset:()=>{Object.assign(prefs(),{keyword:'',type:'',page:1,status:'',role:''});bindGenericInputs();renderRows()},'pick-user':()=>{state.selected=users[0].id;state.quick=true;state.quickTab='credits';renderQuick()},'switch-area':switchArea,
follow:()=>{const f=fund(),followed=state.followed.has(f.id);showModal(followed?'取消关注？':'加入关注？',`<p>${followed?'取消关注':'关注'}“${esc(f.name)}”？</p>`+note('只修改预览中的关注状态。'),followed?'取消关注':'加入关注',()=>{if(followed)state.followed.delete(f.id);else state.followed.add(f.id);if(listing)renderRows();renderQuick();toast('预览关注状态已更新。')},followed)},
'reset-password':()=>showModal('确认重置密码？',`<p>示例账户：${user().mobile}</p>`+note('不修改真实密码，仅演示确认流程。','warning'),'演示重置',()=>toast('重置密码流程已演示。'),true),
grant:()=>form('发放积分',[['amount','积分数量','number','请输入数量'],['reason','发放原因','text','请输入原因']],data=>{user().credits+=Number(data.amount);if(listing)renderRows();renderQuick()}),
'edit-name':()=>form('修改姓名',[['name','姓名','text','请输入姓名']],data=>toast('示例姓名：'+data.name+'，未保存到账户。')),
signout:()=>showModal('退出登录？',note('只演示退出确认，不退出真实会话。'),'演示退出',()=>toast('退出流程演示完成。')),
'manager-detail':()=>{route('managers');state.managerDetail=true;state.section='funds';render()},
'find-manager':()=>{const query=$('#ix-manager-query').value;$('#ix-manager-results').innerHTML=['陈经理','林经理','周经理'].filter(n=>n.includes(query)).map(n=>`<div class="ix-kv"><span>${n} · 示例</span><button class="ix-link" data-ix-manager="${n}">查看详情</button></div>`).join('')||empty('没有找到符合条件的经理')},
'sync-preview':()=>{const t=menus.sync.find(x=>x[0]===$('#ix-sync-task').value);showModal('确认执行任务？',`<p>${esc(t?.[1]||'所选任务')}</p>`+note('这里只演示确认，不启动任何实际任务。','warning'),'演示确认',()=>toast('未启动任何后台任务。'))},
'fee-form':()=>form('维护费率',[['fund','基金代码','text','请输入基金代码'],['fee','费率（%）','number','请输入费率']],()=>{})};
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button||button.disabled)return;const d=button.dataset,text=button.textContent.trim().replace(/\s+/g,'');if(d.ixModule){route(d.ixModule);return}if(d.ixSection){state.section=d.ixSection;state.view='list';closeQuick(false);render();return}if(d.ixOpen){openQuick(d.ixOpen);return}if(d.ixPage){prefs().page=Number(d.ixPage);renderRows();return}if(d.ixDetailSection){const bar=button.closest('.ix-tabs'),offset=bar?.scrollLeft||0;state.detailSection=d.ixDetailSection;renderFull();const next=main.querySelector('.ix-tabs');if(next){next.scrollLeft=offset;next.querySelector('[aria-current=page]')?.scrollIntoView({block:'nearest',inline:'nearest'})}return}if(d.ixQuickTab){state.quickTab=d.ixQuickTab;renderQuick();return}if(d.ixPeriod){refreshChart(d.ixPeriod);return}if(d.ixManager){showModal(d.ixManager+' · 示例资料',kv('在管基金','2 只 · 示例')+kv('任职资料','完整经理资料中查看'),'打开经理详情',()=>actions['manager-detail']());return}if(d.ixEditPlan){plan(d.ixEditPlan);return}if(button.hasAttribute('data-ix-type')){prefs().type=d.ixType;prefs().page=1;renderRows();return}if(d.ixAction){actions[d.ixAction]?.();return}if(button=== $('#ix-modal-submit'))return;
if(/后台|返回前台/.test(text)){switchArea();return}if(/站内提醒/.test(text)){route('notifications');return}if(text==='查询'||text==='筛选'){prefs().page=1;renderRows();toast(text==='筛选'?'已应用当前筛选条件。':'查询完成。');return}if(/模拟买入/.test(text)){buy();return}if(text==='设置定投'||text==='管理计划'){if(text==='管理计划')route('portfolio','plans');else plan();return}if(text==='全部记录'){route('portfolio','orders');return}if(/个人信息|林同学/.test(text)){route('profile');return}if(text==='已关注'){actions.follow();return}const section=menus.portfolio.find(x=>x[1]===text);if(section){route('portfolio',section[0]);return}if(text==='打开完整资料'){enterFull();return}if(['近1月','近3月','近半年','全部'].includes(text)){refreshChart(text);return}if(text==='账户管理')toast('账户管理入口已展开。');else showModal(text||'操作预览',note('此入口保留。当前演示用于比较页面和操作位置，不读取真实业务数据。'));
});
document.addEventListener('input',e=>{const key=e.target.dataset.ixFilter;if(key==='keyword'){prefs().keyword=e.target.value;prefs().page=1;renderRows()}});
document.addEventListener('change',e=>{const key=e.target.dataset.ixFilter;if(!key)return;prefs()[key]=key==='size'?Number(e.target.value):key==='sort'?e.target.value==='true':e.target.value;if(key!=='page')prefs().page=1;renderRows()});
const overlays=document.createElement('div');overlays.innerHTML='<aside class="ix-drawer" id="ix-drawer" aria-label="快速详情" hidden></aside><dialog class="ix-modal" id="ix-modal" aria-labelledby="ix-modal-title"><header class="ix-modal-head"><h2 id="ix-modal-title"></h2><button class="ix-close" data-ix-action="close-modal" aria-label="关闭弹窗">关闭</button></header><div class="ix-modal-body" id="ix-modal-content"></div><footer class="ix-modal-foot"><small>预览演示，不提交真实业务</small><div><button class="ix-button" data-ix-action="close-modal" id="ix-modal-cancel">取消</button><button class="ix-button ix-primary" id="ix-modal-submit">确认预览</button></div></footer></dialog><div class="ix-toast" id="ix-toast" role="status" hidden></div>';document.body.append(overlays);
$('#ix-modal-submit').onclick=()=>{if(modalHandler?.()===false)return;closeModal()};$('#ix-modal').addEventListener('click',e=>{if(e.target===$('#ix-modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});$('#ix-modal').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus()});document.addEventListener('submit',e=>{if(e.target.id==='ix-form'){e.preventDefault();$('#ix-modal-submit').click()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#ix-modal').open&&state.quick)closeQuick()});
const profile=$('.profile');if(profile){const b=document.createElement('button');b.className=profile.className+' ix-profile-button';b.innerHTML=profile.innerHTML;b.dataset.ixAction='profile';profile.replaceWith(b);actions.profile=()=>route('profile')}
