const rootGreen=getComputedStyle(main).getPropertyValue('--green').trim();if(rootGreen)document.documentElement.style.setProperty('--ix-accent',rootGreen);if(scheme==='research')document.documentElement.style.setProperty('--ix-up','#b34d43');
