// Translate vertical wheel input only when the page menu has horizontal overflow.
document.addEventListener('wheel',e=>{if(scheme!=='overview')return;const bar=e.target.closest('.main > .ix-tabs');if(!bar||bar.scrollWidth<=bar.clientWidth||Math.abs(e.deltaX)>Math.abs(e.deltaY))return;const before=bar.scrollLeft;const unit=e.deltaMode===1?20:e.deltaMode===2?bar.clientWidth:1;bar.scrollLeft+=e.deltaY*unit;if(bar.scrollLeft!==before)e.preventDefault()},{passive:false});
// Dismiss the overview drawer before the underlying page handles the click.
document.addEventListener('click',e=>{if(scheme!=='overview'||!state.quick||$('#ix-drawer').hidden||$('#ix-modal').open||e.target.closest('#ix-drawer'))return;e.preventDefault();e.stopImmediatePropagation();closeQuick()},{capture:true});

